  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider, useTheme } from './ThemeContext';
  3→import { LanguageProvider, useTranslation } from './LanguageContext';
  4→import { AgentProvider } from './AgentContext';
  5→import { FileUpload } from './components/FileUpload';
  6→import { QueryEditor } from './components/QueryEditor';
  7→import { ResultsTable } from './components/ResultsTable';
  8→import { ResultMarkdown } from './components/ResultMarkdown';
  9→import { Sidebar } from './components/Sidebar';
 10→import { ErrorMessage } from './components/ErrorMessage';
 11→import { AgentPanel } from './components/AgentPanel';
 12→import type { TableInfo, QueryResult, LangfuseStatus } from './types';
 13→import './App.css';
 14→
 15→function AppContent({ tables, refreshTables, langfuseStatus }: { tables: TableInfo[]; refreshTables: () => Promise<void>; langfuseStatus: LangfuseStatus }) {
 16→  const { theme, toggleTheme } = useTheme();
 17→  const { language, setLanguage, t } = useTranslation();
 18→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 19→  const [error, setError] = useState<string | null>(null);
 20→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 21→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 22→  );
 23→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 24→  const [agentOpen, setAgentOpen] = useState(true);
 25→
 26→  useEffect(() => {
 27→    document.title = t('appTitle');
 28→  }, [t]);
 29→
 30→  useEffect(() => {
 31→    if (tables.length === 0) {
 32→      setQueryResult(null);
 33→      setError(null);
 34→      setEditorQuery(undefined);
 35→    }
 36→  }, [tables]);
 37→
 38→  const handleAgentToggle = () => {
 39→    setAgentOpen((prev) => !prev);
 40→  };
 41→
 42→  const handleLoadSample = useCallback(async () => {
 43→    setError(null);
 44→    try {
 45→      const response = await fetch('/api/upload/sample', { method: 'POST' });
 46→      if (!response.ok) throw new Error('Failed to load sample dataset');
 47→      await refreshTables();
 48→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 49→    } catch (e) {
 50→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 51→    }
 52→  }, [refreshTables]);
 53→
 54→  const handleFileUpload = useCallback(
 55→    async (files: File[]) => {
 56→      setError(null);
 57→      let lastName = '';
 58→      try {
 59→        for (const file of files) {
 60→          const formData = new FormData();
 61→          formData.append('file', file);
 62→          const response = await fetch('/api/upload', {
 63→            method: 'POST',
 64→            body: formData,
 65→          });
 66→          if (!response.ok) throw new Error('Failed to upload file');
 67→          const result = await response.json();
 68→          lastName = result.name;
 69→        }
 70→        await refreshTables();
 71→        if (lastName) {
 72→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
 73→        }
 74→      } catch (e) {
 75→        setError(e instanceof Error ? e.message : 'Failed to upload file');
 76→      }
 77→    },
 78→    [refreshTables]
 79→  );
 80→
 81→  const handleQueryExecute = useCallback(
 82→    async (sql: string) => {
 83→      setError(null);
 84→      setQueryResult(null);
 85→      try {
 86→        const start = performance.now();
 87→        const response = await fetch('/api/query', {
 88→          method: 'POST',
 89→          headers: { 'Content-Type': 'application/json' },
 90→          body: JSON.stringify({ sql }),
 91→        });
 92→        const elapsed = performance.now() - start;
 93→
 94→        if (!response.ok) {
 95→          const errorData = await response.json();
 96→          throw new Error(errorData.detail || 'Query execution failed');
 97→        }
 98→
 99→        const result = await response.json();
100→        setQueryResult({

100→        setQueryResult({
101→          columns: result.columns,
102→          rows: result.rows,
103→          rowCount: result.rowCount,
104→          executionTimeMs: elapsed,
105→          resultType: result.resultType,
106→        });
107→        await refreshTables();
108→      } catch (e) {
109→        setError(e instanceof Error ? e.message : 'Query execution failed');
110→      }
111→    },
112→    [refreshTables]
113→  );
114→
115→  const handleTableClick = useCallback((tableName: string) => {
116→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
117→  }, []);
118→
119→  const handleTableDelete = useCallback(async (tableName: string) => {
120→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
121→    try {
122→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
123→        method: 'DELETE',
124→      });
125→      if (!response.ok) throw new Error('Failed to delete table');
126→      await refreshTables();
127→    } catch (e) {
128→      setError(e instanceof Error ? e.message : 'Failed to delete table');
129→    }
130→  }, [refreshTables, t]);
131→
132→  const appClass = [
133→    'app',
134→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
135→  ].filter(Boolean).join(' ');
136→
137→  const themeIcon = theme === 'dark' ? (
138→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
139→      <circle cx="12" cy="12" r="5" />
140→      <line x1="12" y1="1" x2="12" y2="3" />
141→      <line x1="12" y1="21" x2="12" y2="23" />
142→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
143→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
144→      <line x1="1" y1="12" x2="3" y2="12" />
145→      <line x1="21" y1="12" x2="23" y2="12" />
146→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
147→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
148→    </svg>
149→  ) : (
150→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
151→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
152→    </svg>
153→  );
154→
155→  return (
156→    <div className={appClass}>
157→      <div className="app__sidebar-wrapper">
158→        <Sidebar tables={tables} onTableClick={handleTableClick} onTableDelete={handleTableDelete} collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((prev) => !prev)} />
159→      </div>
160→      {agentOpen ? (
161→        <div className="app__agent-wrapper">
162→          <div className="app__header">
163→            <h1 className="app__title">{t('appTitle')}</h1>
164→            <div className="app__header-actions">
165→              <button
166→                className="app__lang-toggle"
167→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
168→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
169→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
170→              >
171→                {language === 'en' ? 'EN' : '中'}
172→              </button>
173→              <button
174→                className="app__theme-toggle"
175→                onClick={toggleTheme}
176→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
177→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
178→              >
179→                {themeIcon}
180→              </button>
181→              <button
182→                className="app__agent-toggle app__agent-toggle--active"
183→                onClick={handleAgentToggle}
184→              >
185→                {t('editorMode')}
186→              </button>
187→            </div>
188→          </div>
189→          <AgentPanel
190→            langfuseStatus={langfuseStatus}
191→            tables={tables}
192→            onUpload={handleFileUpload}
193→            onLoadSample={handleLoadSample}
194→          />
195→        </div>
196→      ) : (
197→        <div className="app__editor-wrapper">
198→          <div className="app__header">
199→            <h1 className="app__title">{t('appTitle')}</h1>
200→            <div className="app__header-actions">
201→              <button
202→                className="app__lang-toggle"
203→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
204→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
205→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
206→              >
207→                {language === 'en' ? 'EN' : '中'}
208→              </button>
209→              <button
210→                className="app__theme-toggle"
211→                onClick={toggleTheme}
212→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
213→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
214→              >
215→                {themeIcon}
216→              </button>
217→              <button
218→                className="app__agent-toggle"
219→                onClick={handleAgentToggle}
220→              >
221→                {t('agentMode')}
222→              </button>
223→            </div>
224→          </div>
225→          <div className="app__mode-header">
226→            <span className="app__mode-title">{t('editorMode')}</span>
227→          </div>
228→          <main className="app__main">
229→            {tables.length === 0 ? (
230→              <div className="app__empty">
231→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
232→              </div>
233→            ) : (
234→              <>
235→                <QueryEditor
236→                  onExecute={handleQueryExecute}
237→                  initialQuery={editorQuery}
238→                />
239→                {error && (
240→                  <ErrorMessage message={error} onDismiss={() => setError(null)} />
241→                )}
242→                {queryResult?.resultType === 'markdown' ? (
243→                  <ResultMarkdown result={queryResult} />
244→                ) : (
245→                  <ResultsTable result={queryResult} />
246→                )}
247→              </>
248→            )}
249→          </main>
250→        </div>
251→      )}
252→    </div>
253→  );
254→}
255→
256→export default function App() {
257→  const [tables, setTables] = useState<TableInfo[]>([]);
258→  const [loading, setLoading] = useState(true);
259→  const [error, setError] = useState<string | null>(null);
260→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
261→
262→  const refreshTables = useCallback(async () => {
263→    try {
264→      const response = await fetch('/api/tables');
265→      if (!response.ok) throw new Error('Failed to fetch tables');
266→      const data = await response.json();
267→      setTables(data);
268→    } catch (e) {
269→      console.error('Failed to refresh tables:', e);
270→    }
271→  }, []);
272→
273→  useEffect(() => {
274→    (async () => {
275→      try {
276→        const response = await fetch('/api/health');
277→        if (!response.ok) throw new Error('Backend is not available');
278→        await refreshTables();
279→        try {
280→          const lfRes = await fetch('/api/langfuse/status');
281→          if (lfRes.ok) {
282→            setLangfuseStatus(await lfRes.json());
283→          }
284→        } catch {
285→          // Langfuse status fetch is non-critical
286→        }
287→      } catch (e) {
288→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
289→      } finally {
290→        setLoading(false);
291→      }
292→    })();
293→  }, [refreshTables]);
294→
295→  if (loading) {
296→    return <div className="app-loading">Connecting to backend...</div>;
297→  }
298→
299→  if (error) {
300→    return (
301→      <div className="app-error">Failed to connect: {error}</div>
302→    );
303→  }
304→
305→  return (
306→    <LanguageProvider>
307→      <ThemeProvider>
308→        <AgentProvider refreshTables={refreshTables}>
309→          <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
310→        </AgentProvider>
311→      </ThemeProvider>
312→    </LanguageProvider>
313→  );
314→}
